--
-- Backfills wf_inventory.cuisines for every food row using signals we ALREADY
-- hold: google_types[], the name, and wf_editorial prose. No API calls.
--
-- THE RULE: these are FILTER labels over local inventory, never query terms.

with ed as (
  select place_id, lower(coalesce(hook,'') || ' ' || coalesce(why_here,'')) as txt
  from public.wf_editorial
),
src as (
  select i.place_id, lower(i.name) as nm, coalesce(i.google_types,'{}') as tys,
         coalesce(ed.txt,'') as edtxt
  from public.wf_inventory i left join ed on ed.place_id = i.place_id
  where i.category = 'food'
),
vetoed as (
  select place_id from src where
    (nm ~* '\y(nightclub|night club|hookah|cigar)\y')   -- Havana Nights Nightclub is a nightclub — a cuisine label on it is a category error
    or
    (nm ~* '\y(apartments?|realty|salon|barber|storage|dentist|urgent care)\y')   -- a plaza, salon or clinic carrying a cuisine word is not a restaurant
    or
    (nm ~* '\y(outback|texas roadhouse|longhorn steakhouse)\y')   -- national steakhouse chains carry country words that are branding, not cuisine
),
-- Signal tables, emitted as VALUES so thirty regexes are one relation
-- instead of thirty unioned SELECTs.
