),
scoped_veto(cuisine, rx, unless_rx) as (values
  ('japanese','\ykobe\y','japanese|sushi|hibachi|teppan|izakaya')
),
hits as (
  select s.place_id, tm.cuisine, 0.90::numeric as conf, 'google-types'::text as src
    from src s join type_map tm on tm.ty = any(s.tys)
  union all
  select s.place_id, nm2.cuisine, 0.70::numeric, 'name'::text
    from src s join name_map nm2 on s.nm ~* nm2.rx
  union all
  select s.place_id, nm2.cuisine, 0.55::numeric, 'editorial'::text
    from src s join name_map nm2 on s.edtxt <> '' and s.edtxt ~* nm2.rx
),
live as (
  select h.* from hits h
  join src s on s.place_id = h.place_id
  where h.place_id not in (select place_id from vetoed)
    and not exists (
      select 1 from scoped_veto sv
      where sv.cuisine = h.cuisine and s.nm ~* sv.rx
        and (sv.unless_rx is null or s.nm !~* sv.unless_rx))
),
ranked as (
  select place_id, cuisine, max(conf) as conf,
         bool_or(cuisine <> all(array['asian','latin-american','american','mediterranean','caribbean'])) over (partition by place_id) as has_specific
  from live group by place_id, cuisine
),
kept as (
  select place_id, cuisine, conf from ranked
  where has_specific = false or cuisine <> all(array['asian','latin-american','american','mediterranean','caribbean'])
),
agg as (
  select k.place_id,
         array_agg(k.cuisine order by k.conf desc, k.cuisine) as cuisines,
         max(k.conf) as conf,
         (select array_agg(distinct l.src order by l.src) from live l where l.place_id = k.place_id) as srcs
  from kept k group by k.place_id
)
update public.wf_inventory i set
  cuisines           = coalesce(a.cuisines, '{}'),
  cuisine_confidence = a.conf,
  cuisine_sources    = coalesce(a.srcs, case when v.place_id is not null then array['name-veto'] else '{}' end),
  cuisine_reason     = case
                         when v.place_id is not null then 'vetoed: not a cuisine-bearing restaurant'
                         when a.place_id is null then 'unclassifiable'
                         else 'classified' end,
  cuisine_checked_at = now()
from src s
  left join agg a on a.place_id = s.place_id
  left join vetoed v on v.place_id = s.place_id
where i.place_id = s.place_id;
